function decodificarUtf8Base64(base64) {
  const binario = atob(base64);
  const bytes = new Uint8Array(binario.length);
  for (let i = 0; i < binario.length; i += 1) bytes[i] = binario.charCodeAt(i);
  return new TextDecoder("utf-8").decode(bytes);
}

const PATCH_SOURCE = decodificarUtf8Base64(PATCH_BASE64);

self.addEventListener("install", event => {
  event.waitUntil(self.skipWaiting());
});

self.addEventListener("activate", event => {
  event.waitUntil((async () => {
    const chaves = await caches.keys();
    await Promise.all(
      chaves
        .filter(chave => chave.startsWith("op-confeccao-") && chave !== CACHE_NAME)
        .map(chave => caches.delete(chave))
    );

    await self.clients.claim();
    const clientes = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
    await Promise.all(clientes.map(async cliente => {
      cliente.postMessage({ type: "CORPONU_SW_ATIVADO", version: APP_VERSION });
      try {
        const url = new URL(cliente.url);
        if (url.origin !== self.location.origin) return;
        if (url.searchParams.get("corponuAtualizado") === APP_VERSION) return;
        url.searchParams.set("corponuAtualizado", APP_VERSION);
        url.searchParams.set("t", Date.now().toString());
        await cliente.navigate(url.toString());
      } catch (error) {
        // O controllerchange da página continuará como plano B.
      }
    }));
  })());
});

self.addEventListener("message", event => {
  const tipo = event.data?.type;
  if (tipo === "SKIP_WAITING") self.skipWaiting();
  if (tipo === "QUAL_VERSAO" || tipo === "GET_VERSION") {
    event.source?.postMessage({ type: "VERSAO_ATUAL", version: APP_VERSION });
  }
});

function cabecalhosTransformados(response, contentType) {
  const headers = new Headers(response?.headers || {});
  ["content-length", "content-encoding", "etag", "last-modified"].forEach(nome => headers.delete(nome));
  headers.set("content-type", contentType);
  headers.set("cache-control", "no-cache, no-store, must-revalidate");
  headers.set("pragma", "no-cache");
  headers.set("expires", "0");
  return headers;
}

async function buscarSemCache(request, sufixo = "arquivo") {
  const url = new URL(request.url);
  url.searchParams.set("__corponu", APP_VERSION);
  url.searchParams.set("__tipo", sufixo);
  url.searchParams.set("__ts", Date.now().toString());
  return fetch(url.toString(), {
    method: "GET",
    credentials: "same-origin",
    redirect: "follow",
    cache: "no-store",
    headers: { "cache-control": "no-cache" }
  });
}

async function respostaUpdateJs(request) {
  try {
    const response = await buscarSemCache(request, "update");
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    let codigo = await response.text();
    if (!codigo.includes('dataset[DATASET_KEY] ===')) {
      codigo += `

/* CORPONU_PATCH_${APP_VERSION} */
${PATCH_SOURCE}
//# sourceURL=corponu-pagamentos-incorporado.js
`;
    }
    const final = new Response(codigo, {
      status: response.status,
      statusText: response.statusText,
      headers: cabecalhosTransformados(response, "text/javascript; charset=UTF-8")
    });
    const cache = await caches.open(CACHE_NAME);
    await cache.put(request, final.clone());
    return final;
  } catch (error) {
    const cacheado = await caches.match(request);
    if (cacheado) return cacheado;
    throw error;
  }
}

async function respostaPagina(request) {
  try {
    const response = await buscarSemCache(request, "pagina");
    if (!response.ok) return response;
    const final = new Response(await response.arrayBuffer(), {
      status: response.status,
      statusText: response.statusText,
      headers: cabecalhosTransformados(response, response.headers.get("content-type") || "text/html; charset=UTF-8")
    });
    const cache = await caches.open(CACHE_NAME);
    await cache.put(request, final.clone());
    return final;
  } catch (error) {
    return (await caches.match(request)) || (await caches.match("./index.html")) || Response.error();
  }
}

async function respostaArquivoNetworkFirst(request) {
  try {
    const response = await buscarSemCache(request, "asset");
    if (response?.ok) {
      const cache = await caches.open(CACHE_NAME);
      await cache.put(request, response.clone());
    }
    return response;
  } catch (error) {
    const cacheado = await caches.match(request);
    if (cacheado) return cacheado;
    throw error;
  }
}

self.addEventListener("fetch", event => {
  const request = event.request;
  if (request.method !== "GET") return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  const caminho = url.pathname;

  if (caminho.endsWith("/corponu-pagamentos-seguro.js")) {
    event.respondWith(Promise.resolve(new Response(PATCH_SOURCE, {
      headers: {
        "content-type": "text/javascript; charset=UTF-8",
        "cache-control": "no-cache, no-store, must-revalidate"
      }
    })));
    return;
  }

  if (caminho.endsWith("/corponu-release.json")) {
    event.respondWith(Promise.resolve(new Response(JSON.stringify({
      version: APP_VERSION,
      updatedAt: new Date().toISOString(),
      notes: "Recuperação das mudanças financeiras e atualização automática restaurada."
    }), {
      headers: {
        "content-type": "application/json; charset=UTF-8",
        "cache-control": "no-cache, no-store, must-revalidate"
      }
    })));
    return;
  }

  if (caminho.endsWith("/update.js")) {
    event.respondWith(respostaUpdateJs(request));
    return;
  }

  if (request.mode === "navigate" || caminho.endsWith("/") || caminho.endsWith("/index.html")) {
    event.respondWith(respostaPagina(request));
    return;
  }

  if (/\.(?:js|css|json|html)$/i.test(caminho)) {
    event.respondWith(respostaArquivoNetworkFirst(request));
  }
});
